SELECT id, observed_at, created_at, price, source, delivery_status, outcome_reason, ordering_slot FROM market_price_event WHERE symbol='EGLDUSDT' AND observed_at BETWEEN '2026-10-11 22:43:15' AND '2026-10-11 22:43:45' ORDER BY observed_at, id;
SELECT open_time, close_time, open_price, high_price, low_price, close_price, closed, ingestion_source, created_at, updated_at FROM candle WHERE symbol='EGLDUSDT' AND interval_code='1m' AND open_time BETWEEN '2026-10-11 22:40:00' AND '2026-10-11 22:44:00' ORDER BY open_time